#include <iostream>
#include <vector>

int total(const std::vector<int>& releves) {
    int s = 0;
    for (int mm : releves) {
        s += mm;
    }
    return s;
}

int joursDePluie(const std::vector<int>& releves) {
    int jours = 0;
    for (int mm : releves) {
        if (mm > 0) {
            jours++;
        }
    }
    return jours;
}

int record(const std::vector<int>& releves) {
    int r = releves[0];
    for (int mm : releves) {
        if (mm > r) {
            r = mm;
        }
    }
    return r;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> releves;
    for (int i = 0; i < n; i++) {
        int mm;
        std::cin >> mm;
        releves.push_back(mm);
    }
    std::cout << "Total : " << total(releves) << " mm\n";
    std::cout << "Jours de pluie : " << joursDePluie(releves) << "\n";
    std::cout << "Record : " << record(releves) << " mm\n";
    return 0;
}
